local _, addon = ...
addon.localeData.enUS.ambient = {
    GNOME = { "My shield isn't too small. The world is scaled quite unreasonably.", "*retrieves a tiny spanner from a glove and tightens a loose nut.*", "If the mechanism creaks, that's not a fault. It's feedback.", "*tries to measure a dent in the helmet to the nearest millimetre.*", "A plan isn't complete until someone charges into it shouting.", "*writes a number on the shield rim, then rubs it out immediately.*", "Everything on my armour is intentional. Especially the bits still smoking.", "*taps a miniature homemade warning buzzer twice.*" },
    HUMAN = { "The silence before battle is worse than the noise afterward.", "*runs a finger over the faded crest on the shield.*", "Those who stand beside me here are coming home beside me.", "*checks the straps of a comrade's armour one last time.*", "A battle plan is only paper until somebody takes the first step.", "*straightens the ranks with a quick look and gesture.*", "Father always said: be brave. Mother said: come home alive.", "*tightens the gloves and studies the horizon.*" },
    DWARF = { "A warrior without a beard has no excuse for moving so slowly.", "*fishes a breadcrumb from the beard and regards it suspiciously.*", "I won the last battle. Lost the last pint, sadly.", "*polishes a nick in the axe until it looks only half as dangerous.*", "Anyone who calls dwarves stubborn has never argued with a mountain.", "*rattles the shield strap and mutters about cheap craftsmanship.*", "If we survive, I'll buy a round. If not, that'd waste good ale.", "*listens carefully for a bottle clinking in the pack.*" },
    NIGHTELF = { "Some trees I knew were old before this kingdom even had a name.", "*traces a leaf pattern on the weapon hilt.*", "Blood fades. The memory of why we fought remains.", "*stands still for a moment, listening to the forest.*", "A quiet step can protect more than a loud victory.", "*gently removes a leaf from the shoulder and lets it go.*", "The night is not silent today. I will honour it nonetheless.", "*looks into the last light between the trees.*" },
    DRAENEI = { "I have lost one home already. I will not easily lose another.", "*brushes a hand over a small keepsake.*", "Hope need not be shouted to be carried.", "*angles the shield so there is room for someone else behind it.*", "Sometimes courage is nothing more than the next step despite fear.", "*closes the eyes briefly and gathers the thoughts.*", "Those seeking shelter will not have to fall to their knees behind me.", "*checks the edge carefully while keeping an eye on the allies.*" },
    ORC = { "The ancestors won't ask how loudly I roared. They'll ask whom I protected.", "*rubs an old clan charm between thumb and forefinger.*", "A sharp blade needs no great story. The story comes afterward.", "*tightens the leather wrapping on the axe haft.*", "I honour my clan by knowing which fights are worth starting.", "*glances back to see whether the companions are still following.*", "Those behind me are the reason I move forward.", "*strikes the chest once and lifts the chin.*" },
    TROLL = { "If the loa are watching, I ought to look good doing it, heh.", "*lays two small bone beads on the palm and counts them.*", "The old witch doctor said my future was dangerous. Helpful fellow, mon.", "*taps a rapid drum rhythm against the shield.*", "The ancestors tell stories. I give them new ones.", "*tilts the head as though hearing a distant drum.*", "If my plan fails, we'll call it a particularly brave experiment.", "*tucks a loose charm back under the armour.*" },
    TAUREN = { "A mountain speaks little. Everyone understands when it moves.", "*presses one hoof slowly into the ground, testing the footing.*", "I fight so that others may know the peace of the plains again.", "*runs fingers over a braided remembrance band.*", "The Earth Mother asks for no glory. Only responsibility.", "*looks at the sky and takes a deep breath through the nostrils.*", "Those with strength enough to wait know when it is needed.", "*carefully returns a flat stone to its place.*" },
    UNDEAD = { "I've looked worse. Rarely before I died, though.", "*pushes a finger bone back into the glove.*", "The last healer declared me hopeless. Nice fellow.", "*checks the shoulder joint with a dry crack.*", "I sleep poorly. That hasn't been news since my funeral.", "*brushes dirt from an old armour buckle.*", "Anyone who's seen death ought at least to keep a sense of humour.", "*pulls the corners of the mouth up with a faint creak.*" },
    BLOODELF = { "Even a battlefield deserves a little beauty. It seldom gets any.", "*smooths a crease from an exquisitely embroidered sleeve.*", "A sword isn't jewellery. That doesn't mean it must be ugly.", "*adjusts a handguard with an almost imperceptible motion.*", "My ancestors would've argued about my armour. Probably not my courage.", "*regards a dent in the shoulder plate with disdain.*", "I paid good money for this cloak. The enemy would do well to keep its distance.", "*brushes a loose strand of hair aside and settles the helmet carefully.*" },
    NEUTRAL = { "After battle everyone speaks of victory. Beforehand, what matters is who stands.", "*checks the blade and sheathes it calmly.*", "The next step comes easier when you know whom you're taking it for.", "*sets the helmet a little lower and squares the shoulders.*", "A shield is only as strong as the hand that holds it.", "*looks slowly along the allied ranks.*", "Courage isn't the absence of fear. It's a choice.", "*closes a fist around the grip and breathes out slowly.*" },
}
